                  onToggle={onToggle}
                  assignments={assignments}
                  inheritedAssignment={effective}
                  inclusion={inclusion}
                  selection={selection}
                  locked={locked}
                  onPick={onPick}
                  onPreviewFile={onPreviewFile}
                />
              ))}
            </Stack>
          )}
        </Box>
      )}
    </Box>
  )
}

