import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

export interface LocalFile {
  path: string
  name: string
  sizeBytes: number
  isPdf: boolean
  pageCount: number
  corrupt: boolean
}

export interface LocalFileGroup {
  name: string
  files: LocalFile[]
  subgroups: LocalFileGroup[]
}

// Flat, ordered list of every file in the tree (a group's own files, then
// its subgroups' files, recursively). Shared by the upload worker (order to
// process files in), the upload modal's per-group rollup counts, and the
// "every file in this group is done" check driving the Open-in-Drive link —
// one traversal so they can't drift out of sync on how they handle nesting.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  // Resolves to whether a folder was actually picked (false if the user
  // cancelled the dialog), so callers know when a fresh root replaced the
  // previous one and any per-root state (e.g. the upload queue) should reset.
  pickRoot: () => Promise<boolean>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return false

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
    return true
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, useCallback, useEffect } from 'react'
import { LocalFileGroup } from './useFileTree'

export type SelectionItem = { type: 'file'; path: string } | { type: 'group'; key: string }

function itemKey(item: SelectionItem): string {
  return item.type === 'file' ? `file:${item.path}` : `group:${item.key}`
}

export interface SelectionHandle {
  size: number
  items: SelectionItem[]
  isSelected: (item: SelectionItem) => boolean
  // Plain click: replaces the selection with just this item.
  replace: (item: SelectionItem) => void
  // Cmd/Ctrl-click: adds or removes this item from the existing selection.
  toggle: (item: SelectionItem) => void
}

// The shared multi-selection of files and subfolders driving both row
// highlighting and (Step 3e) batch Drive folder assignment — a single
// selection concept rather than a separate preview-only highlight.
export function useSelection(tree: LocalFileGroup | null): SelectionHandle {
  const [selected, setSelected] = useState<Map<string, SelectionItem>>(new Map())

  // Resets on every fresh scan, like inclusion — a new root's rows aren't
  // the ones that were selected under the old one.
  useEffect(() => {
    setSelected(new Map())
  }, [tree])

  const isSelected = useCallback((item: SelectionItem) => selected.has(itemKey(item)), [selected])

  const replace = useCallback((item: SelectionItem) => {
    setSelected(new Map([[itemKey(item), item]]))
  }, [])

  const toggle = useCallback((item: SelectionItem) => {
    setSelected(prev => {
      const key = itemKey(item)
      const next = new Map(prev)
      if (next.has(key)) next.delete(key); else next.set(key, item)
      return next
    })
  }, [])

  return { size: selected.size, items: Array.from(selected.values()), isSelected, replace, toggle }
}

