  // selection, while clicking a subfolder or a non-previewable file leaves
  // it as whatever was last previewed.
  const [previewedFile, setPreviewedFile] = useState<LocalFile | null>(null)
  const [previewedPage, setPreviewedPage] = useState(1)
  const handlePreviewFile = (file: LocalFile) => {
    setPreviewedFile(file)
    setPreviewedPage(1)
  }

  useEffect(() => {
    return () => { if (previewedFile) pageCache.evict(previewedFile.path) }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [previewedFile?.path])

  // Groups start expanded; presence in this set (keyed by the group's full
  // path, e.g. "invoices/2026") means collapsed.
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
  const toggleGroup = (groupKey: string) => {
    setCollapsedGroups(prev => {
      const next = new Set(prev)
      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
      return next
    })
  }

  const inclusion = useInclusion(tree)
  const selection = useSelection(tree)
  const assignments = useDriveAssignments()
  // One or more targets for the currently open folder picker: a single-item
  // array for a per-row badge click, or the pruned multi-selection for the
  // toolbar batch action below — either way, the picked folder applies to
  // every target here.
  const [pickerTargets, setPickerTargets] = useState<SelectionItem[] | null>(null)
  const handlePicked = (folder: DriveAssignment) => {
    for (const target of pickerTargets ?? []) {
      if (target.type === 'group') assignments.setGroupAssignment(target.key, folder)
      else assignments.setFileOverride(target.path, folder)
    }
    setPickerTargets(null)
  }
  const handleBatchAssign = () => {
    if (!tree) return
    setPickerTargets(pruneSelectionForAssignment(tree, selection.items))
  }

  const [uploadModalOpen, setUploadModalOpen] = useState(false)
  // Once Upload All is clicked, the tree locks for the rest of this tree's
  // session — the upload starts immediately, so there's no "in progress but
  // not locked yet" window to account for. Retrying failed files happens
  // inside the upload modal, not from here, so this never needs to go back
  // to false except via a fresh root pick.
  const [started, setStarted] = useState(false)
  const allFiles = tree ? flattenFiles(tree) : []
  const selectedFiles = allFiles.filter(f => inclusion.isFileSelected(f.path))
  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
  const readyToUpload = selectedFiles.length > 0 && selectedFiles.every(f => effectiveAssignments!.get(f.path) != null)

  const handleUploadAll = () => {
    if (!tree || !effectiveAssignments) return
    uploadQueue.start(selectedFiles.map(f => {
      const assignment = effectiveAssignments.get(f.path)
      // Upload All is disabled until readyToUpload is true, so every file
      // should resolve here — this is a defensive check against that
      // guard and this walk drifting out of sync, not an expected path.
      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
    }))
    setStarted(true)
    setUploadModalOpen(true)
  }
  const handlePickRoot = async () => {
    // A new root discards the old tree's upload-queue state along with it —
    // picking a new root is the only way out of the read-only lock.
    if (await pickRoot()) {
      uploadQueue.reset()
      setStarted(false)
    }
  }

  return (
    <Box className={styles.root}>
      <Toolbar>
        <Button size="xs" variant="default" onClick={handlePickRoot}>
          {root ? ellipsisPath(root) : 'Choose root folder…'}
        </Button>
        <Box className={styles.toolbarSpacer} />
        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectAll}>
          Select All
        </Button>
        <Button size="xs" variant="default" disabled={started || !tree} onClick={inclusion.selectNone}>
          Select None
        </Button>
        <Button size="xs" variant="default" disabled={started || !tree || selection.size === 0} onClick={handleBatchAssign}>
          Assign Drive folder…
        </Button>
        <Tooltip
          label={tree ? 'Every selected file needs a Drive folder before uploading' : 'Choose a root folder first'}
          disabled={started || readyToUpload}
        >
          <span>
            <Button size="xs" disabled={started || !readyToUpload} onClick={handleUploadAll}>
              Upload All
            </Button>
          </span>
        </Tooltip>
      </Toolbar>

      <Box className={styles.body}>
        <ResizableLeftPanel
          left={
            <>
              <DriveFolderPickerModal
                opened={pickerTargets !== null}
                onClose={() => setPickerTargets(null)}
                onSelect={handlePicked}
              />
              {tree && (
                <UploadModal
                  opened={uploadModalOpen}
                  tree={tree}
                  onClose={() => setUploadModalOpen(false)}
                />
              )}

              {loading && <Loader size="sm" />}
              {error && <Text size="sm" c="red">{error}</Text>}
              {!loading && !error && isEmpty && (
                <Text size="sm" c="dimmed">No files found under this folder.</Text>
              )}

              {tree && (
                <Stack gap="md">
                  {tree.subgroups.map(group => (
                    <GroupNode
                      key={group.name}
                      group={group}
                      groupKey={group.name}
                      collapsedGroups={collapsedGroups}
                      onToggle={toggleGroup}
                      assignments={assignments}
                      inheritedAssignment={null}
                      inclusion={inclusion}
                      selection={selection}
                      locked={started}
                      onPick={target => setPickerTargets([target])}
                      onPreviewFile={handlePreviewFile}
                    />
                  ))}
                  <FileList
                    files={tree.files}
                    assignments={assignments}
                    inheritedAssignment={null}
                    inclusion={inclusion}
                    selection={selection}
                    locked={started}
                    onPick={target => setPickerTargets([target])}
                    onPreviewFile={handlePreviewFile}
                  />
                </Stack>
              )}
            </>
          }
        >
          <DriveThumbnailPanel
            pdfPath={previewedFile?.path ?? null}
            pageCount={previewedFile?.pageCount ?? 0}
            selectedPage={previewedPage}
            onSelectPage={setPreviewedPage}
          />

          <Box className={styles.detailColumn}>
            {previewedFile && (
              <TruncatedText label={previewedFile.name} size="sm" fw={600} className={styles.detailHeading}>
                {previewedFile.name}
              </TruncatedText>
            )}
            {previewedFile
              ? <DetailPanel pdfPath={previewedFile.path} pageNum={previewedPage} pageCount={previewedFile.pageCount} />
              : <Box className={styles.emptyDetail} />}
          </Box>
        </ResizableLeftPanel>
      </Box>
    </Box>
  )
}

import { LocalFileGroup } from './useFileTree'
import { SelectionItem } from './useSelection'

// The key of the group directly containing groupKey, or null if it's top-level.
function parentGroupKey(groupKey: string): string | null {
  const idx = groupKey.lastIndexOf('/')
  return idx === -1 ? null : groupKey.slice(0, idx)
}

// Maps every file's path to its immediate parent group's key, or null for a
// root-level file with no group to inherit from.
function fileParentKeys(tree: LocalFileGroup): Map<string, string | null> {
  const result = new Map<string, string | null>()
  const walk = (group: LocalFileGroup, groupKey: string | null) => {
    for (const file of group.files) result.set(file.path, groupKey)
    for (const sub of group.subgroups) {
      walk(sub, groupKey !== null ? `${groupKey}/${sub.name}` : sub.name)
    }
  }
  walk(tree, null)
  return result
}

// Whether groupKey or any of its ancestors is in selectedGroupKeys.
function hasSelectedAncestor(groupKey: string | null, selectedGroupKeys: Set<string>): boolean {
  for (let key = groupKey; key !== null; key = parentGroupKey(key)) {
    if (selectedGroupKeys.has(key)) return true
  }
  return false
}

// Drops any selected item that's a descendant of another selected subfolder,
// so a batch assignment gives only the topmost selected item in each
// subtree its own assignment and leaves the rest to inherit it — instead of
// pinning every descendant with a redundant override that could later
// diverge from its ancestor's.
export function pruneSelectionForAssignment(tree: LocalFileGroup, items: SelectionItem[]): SelectionItem[] {
  const selectedGroupKeys = new Set(items.filter(i => i.type === 'group').map(i => i.key))
  const parentKeys = fileParentKeys(tree)

  return items.filter(item => {
    const parentKey = item.type === 'group' ? parentGroupKey(item.key) : parentKeys.get(item.path) ?? null
    return !hasSelectedAncestor(parentKey, selectedGroupKeys)
  })
}

import { ActionIcon, Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import TruncatedText from '../TruncatedText'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import * as uploadQueue from './uploadQueue'
import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const paths = flattenFiles(tree).map(f => f.path)
  const settled = uploadQueue.hasSettled(paths)
  const canResume = settled && uploadQueue.hasPaused(paths)

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} groupKey={group.name} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button
            variant="default"
            disabled={settled && !canResume}
            onClick={() => (canResume ? uploadQueue.resumePaused(paths) : uploadQueue.cancelAll())}
          >
            {canResume ? 'Resume' : 'Cancel'}
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group, groupKey }: { group: LocalFileGroup; groupKey: string }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} groupKey={`${groupKey}/${sub.name}`} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {(status === undefined || status === 'paused') && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {entry && (
        <ActionIcon
          variant="subtle"
          size="sm"
          aria-label={`Open destination Drive folder for ${file.name}`}
